SET status = 'FAILED', fail_time = #{failTime}
WHERE payment_no = #{paymentNo} AND status = #{fromStatus}

UPDATE t_payment
SET channel_transaction_no = #{channelTransactionNo}, channel_pay_url = #{payUrl}
WHERE payment_no = #{paymentNo} AND status = 'PAYING'

